sysevent_script_action.script:
//MSSTRUSTES-113 - Trigger Loopback api
try {
    var outboundid = event.parm1.toString();
    var groutbound = new GlideRecord("x_hsb11_hsbc_mss_o_mss_event_outbound");
    if (groutbound.get(outboundid)) {
        var scheme_code = groutbound.document_id.scheme_code;
        var sub_category = groutbound.document_id.sub_category;
        var payload = groutbound.request_body;
    }
    new x_hsb11_mss_trus_0.MSSTrusteesCallUtils().triggerOutboundRestMessage(payload, outboundid, 'queryERFormInfo', scheme_code, sub_category);
} catch (error) {
    gs.error('MSSTRUSTES-113: An error occurred while triggering the Loopback API. Error: ' + error.message);
}
